head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#e9f1e9" value="#e9f1e9"/><Variable name="page.text" description="Text color" type="color" default="#073e45" value="#073e45"/><Variable name="theme.accent" description="Accent color" type="color" default="#107580" value="#107580"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"Outfit",sans-serif;--body:"DM Sans",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{background:#e9f1e9;color:#073e45;font:14px "DM Sans",sans-serif}header{padding:25px 5vw;border-bottom:1px solid #acc7be}.wordmark{font:600 30px "Outfit",sans-serif;letter-spacing:-.065em}.wordmark span{margin-left:12px;font-size:40px;line-height:0;color:#107580}nav{font-size:12px}.tidal-title{padding:55px 5vw 38px}.eyebrow{font-size:10px;letter-spacing:.14em;font-weight:500;color:#39737a}.tidal-title h1{font:500 clamp(62px,8.4vw,118px)/.95 "Outfit",sans-serif;letter-spacing:-.06em;margin:25px 0}.tidal-title h1 em{font-style:normal;font-weight:400;color:#397b80}.tidal-intro{display:flex;align-items:center;justify-content:space-between}.tidal-intro p{font-size:14px;max-width:480px;color:#3d6b6d}.tidal-intro a{display:flex;width:65px;height:65px;border:1px solid #107580;border-radius:50%;align-items:center;justify-content:center;font-size:30px;text-decoration:none;transition:background .2s}.tidal-intro a:hover{background:#cce1d6}.water-art{margin:0 5vw;overflow:hidden;border-radius:4px}.water-art .art{max-height:550px;object-fit:cover}.image-caption{margin:15px 5vw 0;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.14em;color:#39737a}.habitats{padding:70px 5vw;display:grid;grid-template-columns:.9fr 1.1fr;gap:80px;border-bottom:1px solid #acc7be}.habitats h2{font:500 48px/1.05 "Outfit",sans-serif;letter-spacing:-.045em}.habitat-list a{display:flex;align-items:center;gap:30px;text-decoration:none;border-bottom:1px solid #9bbcaf;padding:27px 0}.habitat-list a:first-child{border-top:1px solid #9bbcaf}.habitat-list span{font-size:10px;color:#39737a}.habitat-list strong{font:400 29px "Outfit",sans-serif;letter-spacing:-.035em}.habitat-list i{margin-left:auto;font-size:24px;font-style:normal;transition:transform .2s}.habitat-list a:hover i{transform:translate(4px,-4px)}.tidal-field{margin:60px 5vw 15px}.section-heading{font:500 47px "Outfit",sans-serif;letter-spacing:-.05em;margin:0 5vw 30px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin:0 5vw}.post-media{aspect-ratio:4/3;border-radius:3px;background:#b7d4c9}.post-meta{font-size:9px;color:#39737a;margin-top:20px}.post-title{font:500 27px/1.15 "Outfit",sans-serif;letter-spacing:-.025em;margin:14px 0}.post-excerpt{font-size:13px;color:#3d6b6d}.observe{margin-top:80px;background:#073e45;color:#e9f1e9;padding:65px 5vw;display:grid;grid-template-columns:1fr 1.1fr;gap:75px}.observe .eyebrow{color:#9dcdc4}.observe h2{font:500 60px/1 "Outfit",sans-serif;letter-spacing:-.04em;margin:25px 0}.observe-title>p:last-child{max-width:300px;color:#afd1c7;font-size:14px}.observe-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.observe-grid article{border-top:1px solid #447980;padding-top:20px}.observe-grid span{font-size:28px;color:#a7d7ba}.observe-grid h3{font:500 20px "Outfit",sans-serif;margin:13px 0}.observe-grid p{font-size:12px;color:#afd1c7}.tidal-closer{text-align:center;padding:60px 5vw}.tidal-closer>p:nth-child(2){font:400 43px/1.15 "Outfit",sans-serif;letter-spacing:-.035em;margin:20px 0 30px}.tidal-closer strong{font-weight:500}.tidal-closer a{font-size:12px;text-underline-offset:6px}footer{padding:35px 5vw;border-top:1px solid #acc7be;font-size:10px;margin-top:0}.tidal-footer{font:500 30px "Outfit",sans-serif;letter-spacing:-.05em}@media(max-width:700px){.tidal-title h1{font-size:65px}.tidal-intro{gap:20px}.tidal-intro a{min-width:50px;width:50px;height:50px}.image-caption span:last-child{display:none}.habitats,.observe{grid-template-columns:1fr;gap:25px}.habitats{padding-top:40px;padding-bottom:40px}.habitats h2{font-size:42px}.posts-grid{grid-template-columns:1fr}.observe h2{font-size:48px}.observe-grid{gap:22px}.tidal-closer>p:nth-child(2){font-size:34px}.water-art .art{min-height:300px}.section-heading{font-size:39px}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
